      "function": "反转点",
      "identity": "负责该公寓的邮递员，年近退休",
      "description": "唯一知道信件实际投递方式的人。在第二幕末尾透露关键信息——这些信不是邮寄来的，是有人直接塞进邮箱的。邮戳是假的。"
    }
  ],
  "relationship_dynamics": "沈予安与陆时清的关系像莫比乌斯环——她因信接近他，因接近爱上他，因爱恐惧失去，因恐惧执行宿命。陆时清的离开是确定的（本来就要搬走），但在女主被信件扭曲的认知里，离开等于失去等于必须在失去之前亲手终结。他的温柔不是拯救，是催化剂。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕：信——建立时间闭环规则，引入核心冲突（信件与宿命），完成女主与男主的第一次接触",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "邮戳上写着三年后",
        "core_event": "沈予安在公寓邮箱中连续收到来自未来的信，只有一句话：不要爱上那个男人。邮戳日期从三年后加速逼近。她在楼道里第一次遇见隔壁的陆时清。",
        "emotional_tone": "不安、好奇、控制欲被激起",
        "key_scenes": [
          "公寓大厅邮箱前——发现第一封信",
          "女主房间——排列三封信的邮戳日期，发现加速规律",
          "楼道——陆时清搬大提琴，两人第一次对视",
          "女主做出决定：主动接近那个男人，证伪信件"
        ]
      }
    ],
    "turning_point": "邮戳日期从三年后跳到两个月后，加速逼近——女主决定主动找到那个男人，用验证来击碎预言"
  },
  "act_two": {
    "description": "第二幕：倒计时——女主从审判者变为沉溺者，信件从预言变为日记，直到真相揭露：投信人就是她自己",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "为了证明你是假的",
        "core_event": "沈予安以借工具为由接触陆时清，带着审判者的眼光观察他，却在相处中逐渐心软。他修琴时的温柔、多煮一杯咖啡的习惯、天台上关于修复的对话，让她的防线出现裂缝。",
        "emotional_tone": "从审视到困惑，第一次心软",
        "key_scenes": [
          "以借工具为由进入陆时清的工作室",
          "女主翻看信件、重新排列邮戳日期",
          "天台共处——他教她听琴弦音准，说'修复不是让它变新的，是让它记住自己的声音'",
          "女主开始在信背面记录与他的相处细节"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "日期越来越近了",
        "core_event": "邮戳逼近到下周。女主意识到自己真的爱上了陆时清。陆时清提到下月搬走。邮递员老周透露信不是邮寄的，是有人直接塞进邮箱。女主深夜守候邮箱，回到房间发现新信已在桌上——日期是明天。她理解了：投信人就是她自己。",
        "emotional_tone": "沉溺、绝望、被宿命碾压的窒息感",
        "key_scenes": [
          "邮戳日期逼近——恐惧与爱意的交织",
          "陆时清提到即将搬离",
          "邮递员老周的关键信息：信不是邮寄来的",
          "深夜守候邮箱——什么也没等到",
          "回房间发现新信在桌上，日期：明天",
          "认知崩塌：她就是投信人，她无法停止"
        ]
      }
    ],
    "turning_point": "女主发现投信人就是她自己——她不是在对抗命运，她就是命运本身。但她无法停止，因为停止意味着承认他的离开只是离开，不是宿命。"
  },
  "act_three": {
    "description": "第三幕：今天——最后一封信的日期到来，女主执行隐喻式的杀人计划，销毁陆时清存在过的一切痕迹，然后亲手写下第一封信，完成时间闭环",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "为了不失去你",
        "core_event": "今天。女主去找陆时清，他已经在打包。最后的对话。然后她执行杀人——不是肉体的杀，是销毁他存在过的一切痕迹：擦掉门框身高标记、扔掉咖啡杯、把修好的琴推下天台。最后她坐在空公寓里写下第一封信：不要爱上那个男人。邮戳日期：三年后。塞进自己的邮箱。循环完成。",
        "emotional_tone": "平静的疯狂、宿命完成时的空洞浪漫",
        "key_scenes": [
          "陆时清半空的公寓——他在打包",
          "两人最后的对话：如果你注定会失去一个人",
          "他离开后——女主逐一销毁他存在的痕迹",
          "天台——琴坠落的声音",
          "空房间里写信——不要爱上那个男人",
          "邮箱盖合上的金属声——循环完成"
        ]
      }
    ],
    "turning_point": "女主将第一封信塞进自己的邮箱，三年后的邮戳——时间闭环完成，宿命不可逃离"
  }
}"}]}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
